import sys

def main():
    d = sys.stdin.readline().strip()
    n = len(d)

    dot = 0
    e = 0
    for i in range(n):
        if d[i] == '.':
            dot = i
        if d[i] == 'e':
            e = i
            break

    b_str = d[e+1:]
    xb = int(b_str)

    output_parts = []
    printed_digits = 0

    for i in range(e):
        if d[i] == '.':
            if e - dot == 2 and d[dot+1] == '0':
                break
            continue

        if i == dot + xb + 1:
            output_parts.append('.')

        output_parts.append(d[i])
        printed_digits += 1

    zero = xb - (e - dot - 1)
    if e - dot == 2 and d[dot+1] == '0':
        zero = xb

    for _ in range(zero):
        output_parts.append('0')

    sys.stdout.write("".join(output_parts) + "\n")

if __name__ == "__main__":
    main()

